#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>
using Matrix = std::vector<std::vector<int>>;
void ClearMarkedLines(Matrix& a) {
    // 쓰기 전에 크기와 직사각형 여부를 전부 검사합니다.
    if (a.size() > 1000) throw std::invalid_argument("too many rows");
    if (a.empty()) return;
    const std::size_t cols = a.front().size();
    if (cols > 1000) throw std::invalid_argument("too many columns");
    for (const auto& row : a)
        if (row.size() != cols) throw std::invalid_argument("ragged matrix");
    if (cols == 0) return;
    bool firstRow = false, firstCol = false;
    for (int v : a.front()) if (v == 0) firstRow = true;
    for (const auto& row : a) if (row[0] == 0) firstCol = true;
    // 안쪽 원본은 아직 바꾸지 않고 가장자리에만 원인을 기록합니다.
    for (std::size_t r = 1; r < a.size(); ++r)
        for (std::size_t c = 1; c < cols; ++c)
            if (a[r][c] == 0) { a[r][0] = 0; a[0][c] = 0; }
    for (std::size_t r = 1; r < a.size(); ++r)
        for (std::size_t c = 1; c < cols; ++c)
            if (a[r][0] == 0 || a[0][c] == 0) a[r][c] = 0;
    // 표식으로 쓰던 가장자리는 마지막에 결과로 바꿉니다.
    if (firstRow) for (auto& v : a[0]) v = 0;
    if (firstCol) for (auto& row : a) row[0] = 0;
}
int main() {
    std::size_t cases = 0;
    // 최대 3x3의 모든 흠집 배치를 독립적인 원본 비교로 검증합니다.
    for (std::size_t rows = 0; rows <= 3; ++rows)
        for (std::size_t cols = 0; cols <= 3; ++cols)
            for (unsigned mask = 0; mask < (1u << (rows * cols)); ++mask) {
                Matrix a(rows, std::vector<int>(cols, 7));
                for (std::size_t r = 0; r < rows; ++r)
                    for (std::size_t c = 0; c < cols; ++c)
                        if (mask & (1u << (r * cols + c))) a[r][c] = 0;
                const Matrix original = a;
                Matrix expected = a;
                for (std::size_t r = 0; r < rows; ++r)
                    for (std::size_t c = 0; c < cols; ++c)
                        if (original[r][c] == 0) {
                            for (std::size_t k = 0; k < cols; ++k) expected[r][k] = 0;
                            for (std::size_t k = 0; k < rows; ++k) expected[k][c] = 0;
                        }
                ClearMarkedLines(a); assert(a == expected); ++cases;
            }
    Matrix bad = {{1, 2}, {3}}, saved = bad;
    bool caught = false;
    try { ClearMarkedLines(bad); } catch (const std::invalid_argument&) { caught = true; }
    assert(caught && bad == saved);
    std::cout << "matrix cases: " << cases << ", ragged preservation: passed\n";
}
